/* Fleet day marks — the mark names, their legend words and the markup builders
 * (design.md "day marks").
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * nothing here varies between apps. Normalized from parking-manager's
 * `day-marks.js`, with its parking-specific status map left in the app: which of
 * your states draws which mark, and which states earn a ring, is the app's own
 * data (see day-marks/README.md "Mapping your states").
 *
 * Pairs with day-marks.css. A mark is an empty span the CSS draws, so there is
 * nothing to escape; an unknown name draws nothing rather than a stray shape.
 */

'use strict';

/** What each mark means, for a legend, in this order: `[mark, label]`. */
export const MARK_WORDS = Object.freeze([
  Object.freeze(['booked', 'Booked']),
  Object.freeze(['will', 'Will book']),
  Object.freeze(['extra', 'Extra day']),
  Object.freeze(['looking', 'Looking']),
  Object.freeze(['off', 'Not booked on purpose']),
]);

const KNOWN = new Set(MARK_WORDS.map(function (pair) { return pair[0]; }));

/**
 * The mark's markup: an empty, decorative span the CSS draws. Say what the day
 * is in the cell's own accessible name, never in the mark.
 *
 * @param {string} mark  one of the five names in MARK_WORDS.
 * @returns {string} the span, or '' for no mark or a name that is not one of the five.
 */
export function markHtml(mark) {
  return KNOWN.has(mark)
    ? '<span class="day-mark" data-mark="' + mark + '" aria-hidden="true"></span>'
    : '';
}

/**
 * The legend: one list item per mark, the mark then its words.
 *
 * @param {ReadonlyArray<readonly [string, string]>} [words]  `[mark, label]` pairs;
 *        the default is MARK_WORDS. Pass a filtered or relabelled list to
 *        match an app that never uses one of the marks, or names them differently.
 * @returns {HTMLUListElement} a `ul.day-legend`.
 */
export function legendEl(words) {
  const ul = document.createElement('ul');
  ul.className = 'day-legend';
  (words || MARK_WORDS).forEach(function (pair) {
    const li = document.createElement('li');
    li.insertAdjacentHTML('beforeend', markHtml(pair[0]));
    li.appendChild(document.createTextNode(pair[1]));
    ul.appendChild(li);
  });
  return ul;
}
